import { useEffect, type RefObject } from 'react';
import { loadConfigFile } from '../../engines/configEngine';

/**
 * Requirement-coverage overlay: colours pink the labels on the Customer 360 main page and the open tab that satisfy a
 * requirement mapped to the active persona in 'Customer 360.xlsx'. The label lists are generated by
 * reference/scripts/audit_customer360_requirements.py into public/config/customer360-requirement-coverage.json.
 * Set SHOW_REQUIREMENT_COVERAGE to false to switch it off.
 */
export const SHOW_REQUIREMENT_COVERAGE = true;

type Coverage = Record<string, Record<string, string[]>>;
let coverage: Promise<Coverage> | undefined;
function loadCoverage(): Promise<Coverage> {
  coverage ??= loadConfigFile<{ personas?: Coverage }>('customer360-requirement-coverage.json')
    .then((j) => j.personas ?? {})
    .catch(() => ({}));
  return coverage;
}

const norm = (t: string | null) => (t ?? '').replace(/\s+/g, ' ').trim().toLowerCase();

/** Applies the pink `req-met` class to leaf elements whose text (or `data-req`, when the display label differs from the requirement's) is a covered label for `personaId`, on the header and `pageKey`. */
export function useRequirementCoverage(root: RefObject<HTMLElement | null>, personaId: string | undefined, pageKey: string, ready: boolean) {
  useEffect(() => {
    if (!SHOW_REQUIREMENT_COVERAGE || !ready || !personaId) return;
    let cancelled = false;
    let observer: MutationObserver | undefined;
    void loadCoverage().then((all) => {
      const el = root.current;
      if (cancelled || !el) return;
      const mine = all[personaId] ?? {};
      const labels = new Set([...(mine.header ?? []), ...(mine[pageKey] ?? [])].map(norm));
      const apply = () => {
        el.querySelectorAll('.req-met').forEach((n) => n.classList.remove('req-met'));
        if (labels.size === 0) return;
        el.querySelectorAll('*').forEach((n) => {
          // The tab rail is navigation, not content.
          // Side drawers that carry their own (non-audit) labels opt out with data-coverage-ignore.
          if (n.children.length === 0 && !n.closest('ol') && !n.closest('[data-coverage-ignore]') && labels.has(norm((n as HTMLElement).dataset?.req ?? n.textContent))) n.classList.add('req-met');
        });
      };
      apply();
      observer = new MutationObserver(apply);
      observer.observe(el, { childList: true, subtree: true, characterData: true });
    });
    return () => {
      cancelled = true;
      observer?.disconnect();
    };
  }, [root, personaId, pageKey, ready]);
}
